// === Выбрать пост: какой пост из outbox публиковать сейчас ===
// Имя файла задаёт время выхода (по Москве):
//   2026-10-19-0900-slug.json  → 19 октября в 09:00
//   2026-10-19-slug.json       → 19 октября, время из Настроек (default_hour)
//   slug.json (без даты)       → сразу
const cfg = $('Настройки').first().json;
const DEFAULT_HOUR = cfg.default_hour;
const MIN_GAP_MINUTES = cfg.min_gap_minutes;
const s = $getWorkflowStaticData('global');
s.lastSentAt = s.lastSentAt || {};
s.chatByFile = s.chatByFile || {};
s.doneFiles = s.doneFiles || {};   // защита от повтора, если файл не удалился из outbox
const now = Date.now();

if (s.pauseUntil && now < s.pauseUntil) return [];   // пауза после ошибки Telegram

function dueAt(name) {
  const m = name.match(/^(\d{4})-(\d{2})-(\d{2})(?:-(\d{2})(\d{2}))?(?=[-_.])/);
  if (!m) return 0;
  let hh = DEFAULT_HOUR, mm = 0;
  if (m[4] !== undefined && +m[4] < 24 && +m[5] < 60) { hh = +m[4]; mm = +m[5]; }
  return Date.UTC(+m[1], +m[2] - 1, +m[3], hh - 3, mm);   // Москва = UTC+3
}

const listed = $input.all().map(i => i.json).filter(f => f.type === 'file' && f.name.endsWith('.json'));
for (const k of Object.keys(s.doneFiles)) if (!listed.some(f => f.name === k)) delete s.doneFiles[k];
const files = listed
  .filter(f => s.doneFiles[f.name] !== f.sha)
  .map(f => ({ ...f, due: dueAt(f.name) }))
  .filter(f => f.due <= now)
  .sort((a, b) => a.due - b.due || a.name.localeCompare(b.name));

for (const f of files) {
  const chat = s.chatByFile[f.name];
  const last = chat ? s.lastSentAt[chat] : undefined;
  if (last && now - last < MIN_GAP_MINUTES * 60000) continue;   // этот канал ещё «отдыхает»
  return [{ json: { name: f.name, sha: f.sha, url: f.url, due: new Date(f.due).toISOString() } }];
}
return [];

// === Подготовить: проверить канал и собрать сообщение ===
const cfg = $('Настройки').first().json;
const ALLOWED = [...cfg.allowed, String(cfg.admin_chat_id || '')].filter(Boolean);
const MIN_GAP_MINUTES = cfg.min_gap_minutes;
const CAPTION_LIMIT = cfg.caption_limit;
const s = $getWorkflowStaticData('global');
s.lastSentAt = s.lastSentAt || {};
s.chatByFile = s.chatByFile || {};
const file = $('Выбрать пост').first().json;
const p = $input.first().json;
const chat = String(p.chat_id || '');
s.chatByFile[file.name] = chat;

const base = { file: file.name, sha: file.sha, id: p.id || file.name.replace(/\.json$/, ''), channel: p.channel || '', chat_id: chat, text_html: p.text_html || '' };

if (!ALLOWED.includes(chat)) {
  return [{ json: { ...base, action: 'reject', reason: 'Канал ' + chat + ' не в белом списке' } }];
}
const last = s.lastSentAt[chat];
if (last && Date.now() - last < MIN_GAP_MINUTES * 60000) return [];   // ждём следующего окна
if (!base.text_html && !p.image_base64) {
  return [{ json: { ...base, action: 'reject', reason: 'В посте нет ни текста, ни картинки' } }];
}

const plain = base.text_html.replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');

if (p.image_base64) {
  const short = plain.length <= CAPTION_LIMIT;
  return [{
    json: { ...base, action: 'photo', caption: short ? base.text_html : '', needText: !short && plain.length > 0 },
    binary: { photo: { data: p.image_base64, mimeType: p.image_mime || 'image/jpeg', fileName: base.id + '.jpg' } }
  }];
}
return [{ json: { ...base, action: 'text', needText: true } }];

// === Итог: записать результат в sent/ ===
const s = $getWorkflowStaticData('global');
s.lastSentAt = s.lastSentAt || {};
s.chatByFile = s.chatByFile || {};
const p = $('Подготовить').first().json;
function mid(node) { try { return $(node).first().json.result.message_id; } catch (e) { return null; } }
const photoId = mid('Отправить картинку');
const textId = mid('Отправить текст');
const lastId = textId || photoId;
s.lastSentAt[p.chat_id] = Date.now();
delete s.chatByFile[p.file];
const record = {
  id: p.id, channel: p.channel, chat_id: p.chat_id,
  photo_message_id: photoId, text_message_id: textId,
  link: 'https://t.me/' + String(p.chat_id).replace('@', '') + '/' + lastId,
  published_at: new Date().toISOString()
};
s.doneFiles = s.doneFiles || {};
s.doneFiles[p.file] = p.sha;
return [{ json: {
  path: 'sent/' + p.id + '.json',
  message: 'sent ' + p.id,
  content: Buffer.from(JSON.stringify(record, null, 2)).toString('base64'),
  file: p.file, sha: p.sha
} }];

// === Ошибка: перенести пост в failed/ и сделать паузу ===
// Пост не теряется: файл целиком копируется в failed/ с описанием ошибки.
const PAUSE_MINUTES = $('Настройки').first().json.pause_minutes;
const s = $getWorkflowStaticData('global');
const p = $('Подготовить').first().json;
const original = $('Скачать пост').first().json;
function mid(node) { try { return $(node).first().json.result.message_id; } catch (e) { return null; } }
const inErr = $input.first().json.error;
const err = inErr ? (inErr.message || JSON.stringify(inErr)) : (p.reason || 'неизвестная ошибка');
const isTelegramError = p.action !== 'reject';
if (isTelegramError) s.pauseUntil = Date.now() + PAUSE_MINUTES * 60000;
const record = { ...original, failed: {
  at: new Date().toISOString(), error: String(err).slice(0, 500),
  photo_already_sent_message_id: mid('Отправить картинку'),
  hint: 'Исправьте причину и верните файл в outbox/. Если фото уже ушло, уберите image_base64.'
} };
const stamp = new Date().toISOString().replace(/[-:]/g, '').slice(0, 13);
s.doneFiles = s.doneFiles || {};
s.doneFiles[p.file] = p.sha;
return [{ json: {
  path: 'failed/' + p.file.replace(/\.json$/, '') + '-' + stamp + '.json',
  message: 'failed ' + p.file,
  content: Buffer.from(JSON.stringify(record, null, 2)).toString('base64'),
  file: p.file, sha: p.sha,
  notify: 'Пост не опубликован: ' + p.file + '\nПричина: ' + String(err).slice(0, 300) + '\nФайл перенесён в failed/.'
} }];

// === НАСТРОЙКИ: единственное место, которое нужно менять ===
return [{ json: {
  repo: 'drokhman/channels-publisher',              // владелец/репозиторий в GitHub
  allowed: ['@chelovek_vs_ai', '@ryadom_repetitor'], // куда разрешено публиковать
  admin_chat_id: '1073319162',          // ваш личный ID в Telegram: сюда приходят ошибки и тестовые посты
  default_hour: 10,           // время выхода, если в имени файла только дата (по Москве)
  min_gap_minutes: 120,       // не чаще одного поста в канал за это время
  pause_minutes: 60,          // пауза после ошибки Telegram
  caption_limit: 1000         // подпись к фото — до 1024 знаков
} }];
